import json,re
C=json.load(open('cars.json'))
N=["2002 Honda S2000","1981 Chevrolet Corvette T-Top","1975 Chevrolet K5 Blazer Cheyenne","2008 Swede Built Chopper","1936 Ford 5-Window Coupe","1988 Lincoln Continental","1957 Ford Thunderbird","2003 Chevrolet S10 LS","1987 Mercedes-Benz 190E 2.3-16","1956 Ford Thunderbird","1986 Mercedes-Benz 420SEC","1977 MG B","2015 Chevrolet Corvette Z06","1991 Porsche 911 Cabriolet","1968 Ford Mustang Convertible","2004 Big Dog Chopper","1961 MG MGA 1600","2022 Ford Bronco","1987 Chevrolet El Camino","1936 Ford Model 68 Woody Wagon","1993 Land Rover Defender 110","1959 AJS Model 20","1985 Aston Martin Vantage Volante","1967 Ford Mustang Fastback","2003 Ferrari 360 Spider","1969 Ford Mustang 428","1941 Ford Super Deluxe Convertible","1942 Harley-Davidson WLA","1999 Jaguar XK8","1993 Land Rover Defender 90 TDi","1990 Land Rover Defender 110 V8","1988 Lotus Excel SE","2019 Mercedes-AMG GT","1977 Porsche 911S Targa","1983 Porsche 911SC Cabriolet","1968 Saab 96"]
for c,n in zip(C,N):
    c['n']=n; p=re.sub(r'[^\d]','',c['price']); c['v']=int(p) if p else None
    c['pd']=('$'+format(c['v'],',')) if c['v'] else 'P.O.A.'
    c['mi']='TMU' if 'TMU' in c['miles'].upper() else c['miles'].split()[0]
    c['body']=c['body'].title().replace('Suv','SUV')
tot=sum(c['v'] for c in C if c['v'])
img=lambda i:C[i]['img']
CSS="""@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,400;9..144,600&family=JetBrains+Mono:wght@500&display=swap');
*{box-sizing:border-box;margin:0;padding:0}body{width:1440px;height:960px;overflow:hidden;font-family:Inter,sans-serif;background:#f4f2ee;color:#16161a;font-size:13px;display:flex;-webkit-font-smoothing:antialiased}
.sb{width:232px;background:#0f0f12;color:#a9a7a2;padding:22px 16px;display:flex;flex-direction:column;gap:4px;flex-shrink:0}
.logo{font-family:Fraunces,serif;color:#f4f2ee;font-size:19px;line-height:1.1;padding:4px 10px 10px}.logo small{display:block;font-family:Inter;font-size:9.5px;letter-spacing:.22em;color:#c8a46a;margin-top:6px}
.nav{padding:6px 10px;border-radius:8px;display:flex;justify-content:space-between}.nav.on{background:#1f1f24;color:#fff}.nav b{font-weight:500;background:#b8322a;color:#fff;border-radius:10px;padding:0 7px;font-size:11px}
.sec{font-size:10px;letter-spacing:.18em;color:#5d5b57;padding:14px 10px 4px}
.demo{margin-top:auto;border:1px dashed #c8a46a;color:#c8a46a;border-radius:8px;padding:10px;font-size:11px;line-height:1.45}
.main{flex:1;padding:22px 30px;overflow:hidden}
.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.top h1{font-family:Fraunces,serif;font-weight:400;font-size:30px;letter-spacing:-.01em}.top p{color:#77746d;margin-top:2px}
.btn{background:#16161a;color:#fff;padding:10px 16px;border-radius:9px;font-weight:500}.btn.g{background:#fff;color:#16161a;border:1px solid #e1ddd5}.btn.r{background:#b8322a}
.row{display:flex;gap:16px}.card{background:#fff;border:1px solid #e7e3db;border-radius:14px;padding:18px}
.k{font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:#8a867e;font-weight:600}
.big{font-family:Fraunces,serif;font-size:34px;margin-top:8px;letter-spacing:-.02em}.up{color:#2f7d4f;font-size:12px;font-weight:600}
.pill{display:inline-block;white-space:nowrap;height:fit-content;padding:3px 9px;border-radius:20px;font-size:11px;font-weight:600}
.p1{background:#eef3fb;color:#2c5ea8}.p2{background:#fbf3e4;color:#9a6a1c}.p3{background:#f9e9e7;color:#b8322a}.p4{background:#e7f3ec;color:#2f7d4f}.p5{background:#efeeea;color:#6b6862}
table{width:100%;border-collapse:collapse}td,th{white-space:nowrap;text-align:left;padding:10px 8px;border-bottom:1px solid #efece6}th{font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:#8a867e;font-weight:600}
.th{width:64px;height:42px;border-radius:7px;background-size:cover;background-position:center;display:inline-block;vertical-align:middle}
.mono{font-family:'JetBrains Mono',monospace;font-size:12px}.mu{color:#8a867e}
.av{width:30px;height:30px;border-radius:50%;background:#e9e2d4;color:#7b5d2a;display:inline-flex;align-items:center;justify-content:center;font-weight:600;font-size:11px}
.search{background:#fff;border:1px solid #e1ddd5;border-radius:9px;padding:10px 14px;width:280px;color:#9a968e}
"""
def nav(on):
    g1=[("Dashboard",""),("Leads","12"),("Pipeline",""),("Customers",""),("Inventory","36"),("Invoices","4")]
    g2=[("Jobs board","23"),("Consignments","3"),("Appraisals","4"),("Storage",""),("Transport","3"),("Finance & insurance",""),("Detailing","5"),("Car finder","4")]
    f=lambda L:"".join(f'<div class="nav{" on" if a==on else ""}"><span>{a}</span>{"<b>"+b+"</b>" if b else ""}</div>' for a,b in L)
    return f'<div class="sb"><div class="logo">The Classic Car Gallery<small>DEALER DESK</small></div><div class="sec">WORKSPACE</div>{f(g1)}<div class="sec">SERVICES</div>{f(g2)}<div class="demo"><b>DEMO DATA</b><br>Customer names, leads, jobs &amp; figures are fictional. Inventory vehicles &amp; asking prices from classiccargallery.com.</div></div>'
def page(on,body,fn):
    open(f'/tmp/crm_{fn}.html','w').write(f'<html><head><meta charset=utf-8><style>{CSS}</style></head><body>{nav(on)}<div class="main">{body}</div></body></html>')
