L=[(0,2,"Offer","Sales","p3"),(1,12,"Viewing","Sales","p2"),(6,None,"New","Storage","p1"),(3,None,"New","Appraisal","p1"),(7,None,"Quoted","Detailing","p2"),(9,None,"New","Car finder","p1")]
