fu=[("Call back · Marcus W.","Blazer · frame-off history","Today 11:00","p3"),("Send photos · Dan O.","Thunderbird · engine bay","Today 3:00","p2"),("Confirm viewing · Elena R.","Corvette Z06 · Saturday","Tomorrow","p1"),("Pick-up · Rafael O.","Transport · Greenwich → Black Rock","Fri","p5")]
